# =============================================================================
# figures/make_figures.R
#
# Code for every computational figure panel in the paper:
#   Figure 1, Supplementary Figure 1    EC identification and subtypes
#   Figure 2, Supplementary Figure 2    ICL prevalence / magnitude
#   Figure 3, 4, 5, Supp. Figures 3-4   T-cell subtypes, trajectories, CellChat,
#                                       spatial examples
# Figure 5C-D are Xenium Explorer screenshots (not generated by code)
# =============================================================================

source("R/utils.R")
suppressPackageStartupMessages({
  library(paletteer)
  library(ggpubr)
  library(ggsci)
  library(ggforce)
  library(ggsignif)
})

EC_LABEL <- "Endothelial"
big_text <- theme(strip.text   = element_text(size = 20),
                  axis.text    = element_text(size = 20),
                  axis.title   = element_text(size = 22),
                  legend.text  = element_text(size = 20),
                  legend.title = element_text(size = 22))

load_all_cells <- function() qs_read(dpath("nsclc_allCells_publicData_useThis_wNormal.qs2"))
load_ecs       <- function() qs_read(dpath("endoAllCells_filtered.qs2"))

# =============================================================================
# Figure 1 -- needs 01_scrna_processing/*, 02_endothelial_cells/*
# =============================================================================
fig1 <- function() {
  allCells_lung <- load_all_cells()
  endoPublic <- load_ecs()

  # 1A: all cells by cell type
  DimPlot(allCells_lung, reduction = "umap", group.by = "celltype_broad") +
    ggtitle(NULL) +
    paletteer::scale_colour_paletteer_d("ggthemes::Miller_Stone") +
    theme(axis.title = element_text(size = 20), axis.text = element_text(size = 18),
          legend.text = element_text(size = 20))
  ggsave(fpath("Fig1A_allCells_cellType_umap.jpg"), width = 7, height = 4)

  # 1B: batch-corrected ECs by subtype
  DimPlot(endoPublic, reduction = "umap", group.by = "ec_subtype") +
    ggtitle("Endothelial Subtype") +
    paletteer::scale_color_paletteer_d("MoMAColors::Klein") +
    theme(axis.title = element_text(size = 20), axis.text = element_text(size = 18),
          legend.text = element_text(size = 20))
  ggsave(fpath("Fig1B_ECs_subtype_umap.jpg"), width = 7, height = 4)

  # 1C: EC subtype composition per sample (samples with >= 20 ECs);
  # two-sided Wilcoxon rank-sum (Mann-Whitney U) between disease states
  subPrevComp <- list(c("LUSC", "LUAD"), c("Normal", "LUAD"), c("Normal", "LUSC"))
  toPlot <- data.frame(sample = endoPublic$sample, subtype = endoPublic$ec_subtype,
                       cancerSubtype = endoPublic$cancerSubtype) %>%
    group_by(sample) %>%
    mutate(nCells = n()) %>%
    dplyr::filter(nCells >= 20) %>%
    ungroup() %>%
    group_by(sample, cancerSubtype, subtype) %>%
    summarize(subtypeProp = n() / nCells, .groups = "drop") %>%
    dplyr::filter(!duplicated(cbind(sample, cancerSubtype, subtype)))

  toPlot %>%
    dplyr::filter(subtype %in% c("gCap", "aCap", "Arterial", "Lymphatic", "Tip", "Stalk", "Venous/PCV")) %>%
    ggplot(aes(x = cancerSubtype, y = subtypeProp)) +
    geom_violin(scale = "width") +
    geom_boxplot(width = 0.1) +
    facet_grid(cols = vars(subtype)) +
    theme_bw() +
    stat_compare_means(comparisons = subPrevComp, method = "wilcox.test",
                       label = "p.signif", label.y.npc = 0.25, size = 6.5) +
    labs(x = "Disease State", y = "Proportion") +
    big_text +
    theme(axis.text.x = element_text(angle = 90, vjust = 0.5, hjust = 1))
  ggsave(fpath("Fig1C_ECsubtype_composition.jpg"), width = 15, height = 6)
}

