# =============================================================================
# Figure 2 and Supplementary Figure 2C -- needs 04_icl_expression/*
# Forest plots: EC vs other cell types, and EC subtype vs other ECs, for
# prevalence (odds ratios) and magnitude among expressors (rate ratios).
# =============================================================================

flag_unstable_estimates <- function(df, or_bounds = c(1e-4, 1e4), max_ci_ratio = 1000) {
  df %>% mutate(ci_ratio = UCL / LCL,
                stable = ratio > or_bounds[1] & ratio < or_bounds[2] & ci_ratio < max_ci_ratio)
}
 
# `df_interaction` (from prev_subtype_group_interaction()) may hold MULTIPLE
# pairwise comparisons for the same subtype+gene once there are 3+ groups
# (LUAD-LUSC, LUAD-Normal, LUSC-Normal); a row is shaded if ANY of its pairwise
# comparisons is significant
plot_forest_by_group <- function(df_group, df_interaction = NULL,
                                 file = fpath("forest_by_group.jpg"),
                                 xlab = "Odds ratio (95% CI)", alpha = 0.05,
                                 drop_unstable = TRUE, show_n = TRUE,
                                 dodge_width = 0.6) {
  d <- flag_unstable_estimates(df_group)
  if (drop_unstable && any(!d$stable)) {
    message(sum(!d$stable), " row(s) dropped from the plot for an implausible OR or CI width ",
            "despite passing the pre-fit separation check -- see flag_unstable_estimates() output:")
    print(d %>% filter(!stable) %>%
            select(any_of(c("group", "gene", "label", "subtype", "ratio", "LCL", "UCL", "ci_ratio"))))
    d <- filter(d, stable)
  }

  hl <- tibble(label = character(0), gene = character(0))
  if (!is.null(df_interaction)) {
    hl <- df_interaction %>% filter(p_adj < alpha) %>% distinct(gene, label)
  }
  p <- ggplot(d, aes(ratio, reorder(label, ratio)))
  if (nrow(hl))                                            
    p <- p + geom_tile(data = hl, aes(x = 1, y = label), inherit.aes = FALSE,
                       width = Inf, height = 1, fill = "grey80", alpha = 0.5)
  p <- p +
    geom_vline(xintercept = 1, linetype = 2) +
    geom_pointrange(aes(xmin = LCL, xmax = UCL, colour = group, shape = p_adj < alpha),
                    position = position_dodge(width = dodge_width), size = 0.5, linewidth = 1) +
    theme(strip.text = element_text(size = 16, angle = 0),
          axis.text = element_text(size = 16),
          axis.title = element_text(size = 20),
          legend.text = element_text(size = 16),
          legend.title = element_text(size = 20)) +
    scale_colour_nejm()
  p <- p +
    scale_shape_manual(values = c(`TRUE` = 16, `FALSE` = 1), name = paste0("adj. p < ", alpha)) +
    scale_x_log10() + facet_wrap(~ gene, scales = "free_x") +
    labs(x = xlab, y = NULL,
         caption = if (nrow(hl)) "Shaded rows: at least one pairwise group comparison significant (Holm within gene)"
                   else NULL) +
    theme_bw() +
    theme(strip.text = element_text(size = 16, angle = 0),
          axis.text = element_text(size = 16),
          axis.title = element_text(size = 20),
          legend.text = element_text(size = 16),
          legend.title = element_text(size = 20)) +
    scale_colour_nejm()
  ggsave(file, p, width = 11, height = 6.5); invisible(p)
}

forest_panels <- function(res, genes, prefix) {
  sel <- function(d) if (is.null(d)) d else dplyr::filter(d, gene %in% genes)
  plot_forest_by_group(sel(res$prevalence$p2a_grp), sel(res$prevalence$p2a_int),
                       fpath(paste0(prefix, "_prevalence_ECvsOther.jpg")),
                       xlab = "Odds ratio, endothelial vs other (95% CI)")
  plot_forest_by_group(sel(res$prevalence$p2bc_grp), sel(res$prevalence$p2bc_int),
                       fpath(paste0(prefix, "_prevalence_ECsubtype.jpg")))
  plot_forest_by_group(sel(res$magnitude$m2a_grp), sel(res$magnitude$m2a_int),
                       fpath(paste0(prefix, "_magnitude_ECvsOther.jpg")),
                       xlab = "Rate ratio, EC vs other, magnitude among expressors (95% CI)")
  plot_forest_by_group(sel(res$magnitude$m2bc_grp), sel(res$magnitude$m2bc_int),
                       fpath(paste0(prefix, "_magnitude_ECsubtype.jpg")),
                       xlab = "Rate ratio, magnitude among expressors (95% CI)")
}

fig2 <- function() {
  all_results <- qs_read(dpath("senstivityStats_all_results.qs2"))
  forest_panels(all_results, c("CD274", "PDCD1LG2"), "Fig2AB_PD1ligands")
  forest_panels(all_results, c("NECTIN2", "PVR"),    "Fig2CD_TIGITligands")
  forest_panels(all_results, c("ACTB", "B2M", "PPIA", "RPL13A"), "SuppFig2C_housekeeping")
}

