supp2 <- function() {
  allCells_lung <- load_all_cells()
  endoPublic <- load_ecs()

  # per-cell expression tables of every ligand and receptor, by disease state
  genGeneExprMats <- function(seu, type, genes) {
    rawCounts <- seu[["RNA"]]$data[genes, ] %>%
      as.data.frame() %>%
      rownames_to_column(var = "gene") %>%
      pivot_longer(-gene, names_to = "barcode", values_to = "expression") %>%
      inner_join(data.frame(barcode = colnames(seu), sample = seu$sample,
                            cellType = seu$celltype_broad), by = "barcode")
    write_tsv(rawCounts, dpath("LungCohort", paste0(type, "_wPublic_rawExpr.tsv")))
  }
  lr_genes <- unique(c(genes_df$ligand, genes_df$receptor))
  for (cancerSub in c("LUAD", "LUSC", "Normal")) {
    subSeu <- if (cancerSub == "Normal") subset(allCells_lung, tissue == "normal") else
      subset(allCells_lung, histology == cancerSub)
    genGeneExprMats(subSeu, cancerSub, genes = lr_genes)
  }

  # S2A: prevalence and magnitude of ICLs across cell categories and EC subtypes
  for (cancerSub in c("LUAD", "LUSC", "Normal")) {
    rawMat <- fread(dpath("LungCohort", paste0(cancerSub, "_wPublic_rawExpr.tsv"))) %>%
      mutate(category = case_when(cellType %in% c("B", "T", "Myeloid") ~ "Immune",
                                  cellType %in% c("Fibroblast", "Pericyte") ~ "Mesenchymal",
                                  .default = cellType),
             cellType = case_when(cellType %in% c("B", "NK/T", "Mast", "Myeloid") ~ "Immune",
                                  cellType %in% c("Fibroblast", "Pericyte") ~ "Mesenchymal",
                                  .default = cellType),
             cellType = ifelse(category == "Endothelial", "All ECs", cellType),
             ligand = gene) %>%
      dplyr::filter(ligand %in% genes_df$ligand) %>%
      group_by(category, cellType, ligand) %>%
      summarize(meanExp = mean(expression), propExp = sum(expression > 0) / n(), .groups = "drop")

    subECs <- subset(endoPublic, cancerSubtype == cancerSub)
    ecMat <- subECs[["RNA"]]$data[unique(genes_df$ligand), ] %>%
      as.data.frame() %>%
      rownames_to_column(var = "ligand") %>%
      pivot_longer(-ligand, names_to = "barcode", values_to = "expression") %>%
      inner_join(data.frame(barcode = colnames(subECs), sample = subECs$sample,
                            cellType = subECs$ec_subtype, category = "Endothelial"), by = "barcode") %>%
      group_by(category, cellType, ligand) %>%
      summarize(meanExp = mean(expression), propExp = sum(expression > 0) / n(), .groups = "drop")

    plot <- rbind(rawMat, ecMat) %>%
      dplyr::filter(!is.na(cellType)) %>%
      left_join(genes_df, by = "ligand") %>%
      ggplot(aes(x = cellType, y = ligand, size = propExp * 100, colour = meanExp)) +
      geom_point() +
      facet_grid(cols = vars(category), rows = vars(receptor), scales = "free", space = "free") +
      theme_bw() +
      paletteer::scale_color_paletteer_c("grDevices::Viridis", limits = c(0, 1.75)) +
      scale_size_continuous(limits = c(0, 85)) +
      theme(axis.text.x = element_text(angle = 90, vjust = 0.5, hjust = 1),
            strip.text.x = element_text(size = 18, angle = 90),
            strip.text.y = element_text(size = 16, angle = 0),
            axis.text = element_text(size = 18), axis.title = element_text(size = 22),
            legend.text = element_text(size = 20), legend.title = element_text(size = 22)) +
      labs(y = "Ligand", x = "Cell Subtype", colour = "Normalized Mean\nExpression",
           size = "Proportion\nof Cells")
    ggsave(fpath(paste0("SuppFig2A_ICL_dotplot_", cancerSub, ".jpg")), plot = plot, width = 10, height = 10)
  }

  # S2B: magnitude (expressors) and prevalence of the four ICLs
  icl <- c("NECTIN2", "PVR", "PDCD1LG2", "CD274")
  toPlot <- data.frame(sample = allCells_lung$sample, cellType = allCells_lung$celltype_broad,
                       cancerSubtype = allCells_lung$cancerSubtype) %>%
    cbind(t(allCells_lung[["RNA"]]$data[icl, ]) %>% as.data.frame()) %>%
    mutate(cellType_simple = case_when(cellType %in% c("B", "T", "Myeloid") ~ "Immune",
                                       cellType %in% c("Fibroblast", "Pericyte") ~ "Mesenchymal",
                                       .default = cellType))
  toPlot$subtype <- toPlot$cellType_simple
  toPlot <- rbind(toPlot,
    data.frame(sample = endoPublic$sample, cellType = "Endothelial",
               cancerSubtype = endoPublic$cancerSubtype, cellType_simple = "Endothelial",
               subtype = endoPublic$ec_subtype) %>%
      cbind(t(endoPublic[["RNA"]]$data[icl, ]) %>% as.data.frame()))
  toPlot <- pivot_longer(toPlot, cols = all_of(icl), names_to = "gene", values_to = "expr")
  toPlot$subtype <- factor(toPlot$subtype, levels = c("Endothelial", "Arterial", "aCap", "gCap", "EndMT",
                                                      "Lymphatic", "Proliferative", "Stalk", "Tip", "Venous/PCV",
                                                      "Malignant", "Epithelial", "Mesenchymal", "Immune"))
  toPlot$gene <- factor(toPlot$gene, levels = c("CD274", "PDCD1LG2", "NECTIN2", "PVR"))

  toPlot %>%
    group_by(cancerSubtype, gene, subtype) %>%
    mutate(propExpr = sum(expr > 0) / n()) %>%
    ungroup() %>%
    dplyr::filter(expr > 0) %>%
    ggplot(aes(x = subtype, y = log10(expr + 1), fill = log10(propExpr * 100))) +
    geom_violin(scale = "width") +
    geom_boxplot(width = 0.1) +
    facet_grid(rows = vars(gene), cols = vars(cancerSubtype), scale = "free_x", space = "free_x") +
    theme_bw() +
    labs(x = "Cell Type", y = "Log10(Mean Expression + 1)", fill = "Log10(Percent\nExpressing)") +
    paletteer::scale_fill_paletteer_c("grDevices::Viridis") +
    big_text +
    theme(axis.text.x = element_text(angle = 90, vjust = 0.5, hjust = 1)) +
    coord_flip()
  ggsave(fpath("SuppFig2B_ICL_violins.jpg"), height = 25, width = 10)
}

