## ---------------------------------------------------------------------------

pathway_labels <- c(
  CD274_PDCD1    = "PD-L1 (CD274) -> PD-1",
  PDCD1LG2_PDCD1 = "PD-L2 (PDCD1LG2) -> PD-1",
  NECTIN2_TIGIT  = "NECTIN2 -> TIGIT",
  PVR_TIGIT      = "PVR -> TIGIT"
)

sender_order  <- c(EC_LABEL, "Myeloid", "Malignant", "Epithelial", "Fibroblast")
disease_order <- c("Normal", "LUAD", "LUSC")

pd1_pathways   <- c("CD274_PDCD1", "PDCD1LG2_PDCD1")
tigit_pathways <- c("NECTIN2_TIGIT", "PVR_TIGIT")

# Facet label for any `interaction` value
interaction_label <- function(x) {
  unname(ifelse(x %in% names(pathway_labels), pathway_labels[x],
                paste0(gsub("_", " -> ", x), " (positive control)")))
}

## ---------------------------------------------------------------------------
## Significance brackets: `ref_level` (EC) vs every other level of `x_col`,
## computed SEPARATELY within each combination of `facet_cols` present in
## `data`, via a two-sided Wilcoxon rank-sum test. 
## ---------------------------------------------------------------------------
sig_brackets_vs_ref <- function(data, x_col, y_col, facet_cols, ref_level,
                                p_adjust_method = "BH", alpha = 0.05) {
  other_levels <- setdiff(unique(as.character(data[[x_col]])), ref_level)
  facet_keys <- data %>% distinct(across(all_of(facet_cols)))
  brackets <- pmap_dfr(facet_keys, function(...) {
    key <- tibble(...)
    d_facet <- data %>% semi_join(key, by = facet_cols)
    map_dfr(other_levels, function(lvl) {
      a <- d_facet[[y_col]][as.character(d_facet[[x_col]]) == ref_level]
      b <- d_facet[[y_col]][as.character(d_facet[[x_col]]) == lvl]
      if (length(a) < 2 || length(b) < 2) return(NULL)
      wt <- tryCatch(suppressWarnings(wilcox.test(a, b)), error = function(e) NULL)
      if (is.null(wt)) return(NULL)
      bind_cols(key, tibble(group1 = ref_level, group2 = lvl,
                            n1 = length(a), n2 = length(b),
                            y_max_facet = max(c(a, b), na.rm = TRUE),
                            p = wt$p.value))
    })
  })
  if (nrow(brackets) == 0) return(brackets)
  brackets %>%
    group_by(across(all_of(facet_cols))) %>%
    mutate(p_adj = p.adjust(p, method = p_adjust_method),
          label  = case_when(p_adj < 0.001 ~ "***", p_adj < 0.01 ~ "**",
                              p_adj < alpha ~ "*",  TRUE ~ "ns"),
          y_position = max(y_max_facet) * (1.2 + 0.2 * (row_number() - 1))) %>%
    ungroup() %>%
    drop_na()
}

## ---------------------------------------------------------------------------
## Panel A: EC vs other major cell types, one T-cell split, faceted by
## ligand (rows) x disease state (columns)
## ---------------------------------------------------------------------------
make_panel_A <- function(bench_tbl, pathways, sample_meta_grp, title) {
  d <- bench_tbl %>%
    filter(interaction %in% pathways) %>%
    left_join(sample_meta_grp %>% select(sample, group), by = "sample") %>%
    filter(!is.na(group)) %>%
    mutate(source       = factor(source, levels = intersect(sender_order, unique(source))),
          group         = factor(group, levels = intersect(disease_order, unique(as.character(group)))),
          ligand_label  = factor(pathway_labels[interaction], levels = unname(pathway_labels[pathways])))

  brackets <- sig_brackets_vs_ref(d, x_col = "source", y_col = "prob_max",
                                  facet_cols = c("ligand_label", "group"),
                                  ref_level = EC_LABEL)

  p <- ggplot(d, aes(x = source, y = prob_max)) +
    geom_boxplot(outlier.size = 0.6) +
    facet_grid(rows = vars(ligand_label), cols = vars(group), scales = "free_y") +
    labs(x = "Sender (-> T cells)", y = "Max communication probability (per sample)",
        subtitle = title) +
    theme_bw() + theme(legend.position = "none", axis.text.x = element_text(angle = 45, hjust = 1)) +
    theme(strip.text = element_text(size = 16, angle = 0),
          axis.text = element_text(size = 16),
          axis.title = element_text(size = 20),
          legend.text = element_text(size = 16),
          legend.title = element_text(size = 20))

  if (nrow(brackets) > 0) {
    p <- p + geom_signif(data = brackets,
                         aes(xmin = group1, xmax = group2, y_position = y_position,
                             annotations = label),
                         manual = TRUE, inherit.aes = FALSE, tip_length = 0.01, textsize = 3)
  }
  list(plot = p, brackets = brackets)
}

## ---------------------------------------------------------------------------
## Panel B: target pathway(s) vs matched expression-level negative controls
## ---------------------------------------------------------------------------
wilcox_by_target_group_local <- function(mag_tbl) {
  mag_tbl %>%
    distinct(target, group) %>%
    pmap_dfr(function(target, group) {
      dd <- filter(mag_tbl, target == !!target, group == !!group)
      tp <- dd$prob_max[dd$role == "Target pathway (EC -> T)"]
      nc <- dd$prob_max[dd$role == "Matched negative controls"]
      if (length(tp) < 2 || length(nc) < 2) return(NULL)
      wt <- suppressWarnings(wilcox.test(tp, nc, alternative = "greater"))
      tibble(target = target, group = group,
            n_target_samples = length(tp), n_control_obs = length(nc),
            median_target = median(tp), median_control = median(nc),
            frac_detected_target  = mean(tp > 0),
            frac_detected_control = mean(nc > 0),
            p_wilcox = wt$p.value)
    })
}
 
make_panel_B <- function(mag_tbl, pathways, sample_meta_grp, title) {
  d <- mag_tbl %>%
    filter(target %in% pathways) %>%
    left_join(sample_meta_grp %>% select(sample, group), by = "sample") %>%
    filter(!is.na(group)) %>%
    mutate(target_label = factor(pathway_labels[target], levels = unname(pathway_labels[pathways])),
          group        = factor(group, levels = intersect(disease_order, unique(as.character(group)))),
          role         = factor(role, levels = c("Target pathway (EC -> T)", "Matched negative controls")))
 
  wtab <- wilcox_by_target_group_local(d)
  y_max_by_facet <- d %>% group_by(target, group) %>%
    summarise(y_max = max(prob_max, na.rm = TRUE), .groups = "drop")
 
  ann <- wtab %>%
    left_join(y_max_by_facet, by = c("target", "group")) %>%
    mutate(target_label = factor(pathway_labels[target], levels = unname(pathway_labels[pathways])),
          group        = factor(group, levels = intersect(disease_order, unique(as.character(group)))),
          label = paste0("p = ", signif(p_wilcox, 2), "\ndet: ",
                        sprintf("%.0f%%", 100 * frac_detected_target), " vs ",
                        sprintf("%.0f%%", 100 * frac_detected_control)),
          y_position = y_max * 1.12)
 
  list(
    plot = ggplot(d, aes(x = role, y = prob_max, fill = role)) +
      geom_boxplot(outlier.size = 0.6) +
      facet_grid(rows = vars(target_label), cols = vars(group), scales = "free_y") +
      geom_text(data = ann, aes(x = 1.5, y = y_position, label = label),
                inherit.aes = FALSE, size = 5, lineheight = 0.9) +
      labs(x = NULL, y = "Communication probability (EC -> T, per sample)", subtitle = title) +
      theme_bw() + theme(legend.position = "bottom") +
      theme(strip.text = element_text(size = 16, angle = 0),
            axis.text = element_text(size = 16),
            axis.title = element_text(size = 20),
            legend.text = element_text(size = 16),
            legend.title = element_text(size = 20)),
    wilcox = wtab
  )
}

## ---------------------------------------------------------------------------
## Panel B, EC-SUBTYPE resolved version
## ---------------------------------------------------------------------------
signal_bearing_subtypes <- function(dot_tab, pathways) {
  dot_tab %>% filter(interaction %in% pathways, frac_sig > 0) %>% pull(source) %>% unique()
}
 
wilcox_by_target_source_group_local <- function(mag_tbl) {
  mag_tbl %>%
    distinct(target, source, group) %>%
    pmap_dfr(function(target, source, group) {
      dd <- filter(mag_tbl, target == !!target, source == !!source, group == !!group)
      tp <- dd$prob_max[dd$role == "Target pathway (EC subtype -> T)"]
      nc <- dd$prob_max[dd$role == "Matched negative controls"]
      if (length(tp) < 2 || length(nc) < 2) return(NULL)
      wt <- suppressWarnings(wilcox.test(tp, nc, alternative = "greater"))
      tibble(target = target, source = source, group = group,
            n_target_samples = length(tp), n_control_obs = length(nc),
            median_target = median(tp), median_control = median(nc),
            frac_detected_target  = mean(tp > 0),
            frac_detected_control = mean(nc > 0),
            p_wilcox = wt$p.value)
    })
}
 
make_panel_B_ecsub <- function(mag_tbl, pathways, dot_tab_for_subtype_selection, sample_meta_grp, title) {
  subtypes <- signal_bearing_subtypes(dot_tab_for_subtype_selection, pathways)
  if (length(subtypes) == 0) {
    warning(title, ": no EC subtype had any significant call (frac_sig > 0) for ",
            paste(pathways, collapse = ", "), " in the panel-C dot-plot table -- ",
            "nothing to plot here. Returning NULL (skipped in the save loop below).")
    return(NULL)
  }
 
  d <- mag_tbl %>%
    filter(target %in% pathways, source %in% subtypes) %>%
    left_join(sample_meta_grp %>% select(sample, group), by = "sample") %>%
    filter(!is.na(group)) %>%
    mutate(target_label = factor(pathway_labels[target], levels = unname(pathway_labels[pathways])),
          group        = factor(group, levels = intersect(disease_order, unique(as.character(group)))),
          source       = factor(source, levels = intersect(subtypes, unique(source))),
          role         = factor(role, levels = c("Target pathway (EC subtype -> T)", "Matched negative controls"))) %>%
    dplyr::filter(group != "Normal")
 
  wtab <- wilcox_by_target_source_group_local(d)
  y_max_by_facet <- d %>% group_by(target, source, group) %>%
    summarise(y_max = max(prob_max, na.rm = TRUE), .groups = "drop")
 
  ann <- wtab %>%
    left_join(y_max_by_facet, by = c("target", "source", "group")) %>%
    mutate(target_label = factor(pathway_labels[target], levels = unname(pathway_labels[pathways])),
          group        = factor(group, levels = intersect(disease_order, unique(as.character(group)))),
          source       = factor(source, levels = intersect(subtypes, unique(source))),
          label = paste0("p = ", signif(p_wilcox, 2), "\ndet: ",
                        sprintf("%.0f%%", 100 * frac_detected_target), " vs ",
                        sprintf("%.0f%%", 100 * frac_detected_control)),
          y_position = y_max * 1.14)
 
  list(
    plot = ggplot(d, aes(x = role, y = prob_max)) +
      geom_boxplot(outlier.size = 0.5) +
      facet_grid(cols = vars(target_label, source), rows = vars(group), scales = "free_y") +
      geom_text(data = ann, aes(x = 1.5, y = y_position, label = label),
                inherit.aes = FALSE, size = 5, lineheight = 0.85) +
      labs(x = NULL, y = "Communication probability (EC subtype -> T, per sample)", subtitle = title) +
      theme_bw() + theme(legend.position = "bottom") +
      theme(strip.text = element_text(size = 16, angle = 0),
            axis.text = element_text(size = 16),
            axis.title = element_text(size = 20),
            legend.text = element_text(size = 16),
            legend.title = element_text(size = 20)),
    wilcox = wtab,
    subtypes_plotted = subtypes
  )
}

## ---------------------------------------------------------------------------
## Panel C: EC subtype x fine T-cell-subtype dot plot
## ---------------------------------------------------------------------------
make_panel_C <- function(dot_tab, pathways, title) {
  d <- dot_tab %>%
    filter(interaction %in% pathways,
          group != "Normal",
          target != "CD4") %>%
    mutate(ligand_label = factor(interaction_label(interaction), levels = unique(interaction_label(pathways))),
          group         = factor(group, levels = intersect(disease_order, unique(as.character(group)))))

  ggplot(d, aes(y = target, x = source)) +
    geom_point(aes(size = frac_sig, colour = median_prob_sig)) +
    scale_colour_viridis_c(name = "Interaction probability\n(significant samples only)", na.value = "grey85") +
    scale_size_continuous(name = "Fraction of testable\nsamples significant", range = c(0.5, 8)) +
    facet_grid(rows = vars(ligand_label), cols = vars(group), scales = "free") +
    labs(y = "Fine T-cell subtype", x = "EC subtype", subtitle = title) +
    theme_bw() + theme(axis.text.x = element_text(angle = 45, hjust = 1)) +
      theme(strip.text = element_text(size = 16, angle = 0),
            # strip.text.y = element_text(angle = 0),
            axis.text = element_text(size = 16),
            axis.title = element_text(size = 20),
            legend.text = element_text(size = 16),
            legend.title = element_text(size = 20))
}


