# =============================================================================
# CODEX example regions -- Figure 3B-C (CD4) and 4D-E (CD8)
# Needs 06_spatial/*
# =============================================================================
codex <- function() {
  mat <- readMM(dpath("counts_nsclcCODEX.mtx"))
  barcodes <- fread(dpath("barcodes_nsclcCODEX.tsv"))
  features <- read_tsv(dpath("features_nsclcCODEX.tsv"), col_names = FALSE)
  meta <- fread(dpath("metadata_nsclcCODEX.tsv"))
  rownames(mat) <- barcodes$V1
  colnames(mat) <- features$X1
  meta$V1 <- as.character(meta$V1)
  res <- fread(dpath("lung_codexRes_10um.csv"))

  plot_marker_overlay <- function(meta_core, marker, pair_cells) {
    ggplot(meta_core) +
      geom_ellipse(aes(x0 = x, y0 = y, a = max / 2, b = min / 2,
                       fill = .data[[marker]], angle = 0), alpha = 0.1) +
      geom_ellipse(data = dplyr::filter(meta_core, CellID %in% pair_cells$CellID),
                   aes(x0 = x, y0 = y, a = max / 2, b = min / 2,
                       fill = .data[[marker]], angle = 0, colour = phenotype),
                   linewidth = 2) +
      paletteer::scale_fill_paletteer_c("grDevices::Viridis") +
      paletteer::scale_color_paletteer_d("trekcolors::starfleet") +
      labs(colour = "Cell Type") +
      theme_void() +
      theme(strip.text.x = element_text(size = 20), strip.text.y = element_text(size = 20),
            legend.text = element_text(size = 20), legend.title = element_text(size = 22))
  }

  # One example: patient, T-cell type in `res` ("Tc" = CD8, "Th" = CD4), the
  # T-cell marker, and which candidate pair (row of vt_pairs) to draw.
  make_example <- function(patient, t_phenotype, t_marker, pair_index, out_prefix) {
    t_label <- if (t_phenotype == "Tc") "CD8+ T" else "CD4+ T"
    cells <- meta |>
      dplyr::filter(patient_id == patient) %>%
      transmute(CellID, V1, phenotype,
                x = `Centroid X µm`, y = `Centroid Y µm`,
                max = `Cell: Max diameter µm`, min = `Cell: Min diameter µm`)
    cells <- left_join(cells, rownames_to_column(as.data.frame(as.matrix(mat)), var = "CellID"),
                       by = c("V1" = "CellID"))
    markers <- c("CD31", t_marker, "PD-1", "PD-L1")
    cells <- cells |>
      mutate(across(all_of(markers), ~ (. - min(., na.rm = TRUE)) /
                      (max(., na.rm = TRUE) - min(., na.rm = TRUE))))

    vt_pairs <- res |>
      mutate(T_cell_type = ifelse(T_cell_type == t_phenotype, t_label, T_cell_type),
             adj_cell_type = ifelse(adj_cell_type == "Vascular", "Endothelial", adj_cell_type)) %>%
      dplyr::filter(T_cell_type == t_label, adj_cell_type == "Endothelial",
                    T_cell_id %in% cells$CellID) %>%
      inner_join(cells, by = c("T_cell_id" = "CellID")) %>%
      dplyr::filter((.data[[t_marker]] > quantile(cells[[t_marker]], 0.95) &
                       `PD-1` > quantile(cells$`PD-1`, 0.95) & `PD-L1` < quantile(cells$`PD-L1`, 0.9)) |
                      (CD31 > quantile(cells$CD31, 0.95) & `PD-L1` > quantile(cells$`PD-L1`, 0.95) &
                         `PD-1` < quantile(cells$`PD-1`, 0.9)))

    pair <- vt_pairs[pair_index, ]
    pair_cells <- cells |> dplyr::filter(CellID %in% c(pair$T_cell_id, pair$adj_cell_id))
    roi_center <- pair_cells |> summarize(cx = mean(x), cy = mean(y))
    roi_cells <- cells |>
      mutate(dist = sqrt((x - roi_center$cx)^2 + (y - roi_center$cy)^2)) |>
      dplyr::filter(dist <= 50) %>%
      mutate(phenotype = ifelse(phenotype == t_phenotype, t_label, phenotype),
             phenotype = ifelse(phenotype == "Vascular", "Endothelial", phenotype))

    for (m in markers) {
      plot_marker_overlay(roi_cells, m, pair_cells)
      ggsave(fpath(paste0(out_prefix, "_", gsub("-", "", m), ".jpg")), width = 4, height = 3)
    }
  }

  examples <- tribble(
    ~panel,    ~patient, ~t_phenotype, ~t_marker, ~pair_index,
    "Fig4D",   "P_39",   "Tc",         "CD8",     5,
    "Fig3B",   "P_36",   "Th",         "CD4",     1,
    "Fig3C",   "P_10",   "Th",         "CD4",     2,
    "Fig4E",   "P_38",   "Tc",         "CD8",     1)
  for (i in seq_len(nrow(examples))) {
    ex <- examples[i, ]
    if (is.na(ex$patient) || is.na(ex$pair_index)) {
      message(ex$panel, ": example region not specified yet -- skipped"); next
    }
    make_example(ex$patient, ex$t_phenotype, ex$t_marker, ex$pair_index,
                 paste0(ex$panel, "_codex_", ex$patient))
  }
}

# =============================================================================
# CosMx example regions -- Figure 3D-E (CD4) and 4F-G (CD8)
# =============================================================================
cosmx <- function() {
  adjacentOtherTs_filtered_cellTyped <- fread(dpath("SpatialCohort", "allTCell_ligInteractions.csv"))
  allCellIdents <- fread(dpath("SpatialCohort", "allCellIdents.csv"))

  make_example <- function(f, fov_use, ligand, t_gene, xlim, ylim, out_file) {
    samplePath <- file.path(COSMX_RAW_DIR, f, paste0(f, "-Flat_files_and_images"))
    tx   <- fread(file.path(samplePath, paste0(f, "_tx_file.csv")))
    segs <- fread(file.path(samplePath, paste0(f, "_polygons2.csv")))
    nano <- qs_read(dpath("SpatialCohort", f, "nanostrObj.qs2"))

    test_tx <- tx %>% dplyr::filter(cell_ID != 0, target %in% c("PECAM1", t_gene, "PDCD1", ligand))
    tPos <- sub("\\..*$", "", colnames(nano)[which(nano[["Nanostring"]]$counts[t_gene, ] > 0)])
    inter <- adjacentOtherTs_filtered_cellTyped %>%
      dplyr::filter(grepl("PDCD1", pair), sample == f,
                    cellType == "Endothelial", t_cell %in% tPos)

    test_segs <- segs %>% dplyr::filter(fov == fov_use) %>% mutate(barcode = paste(cellID, fov, sep = "_"))
    tx2 <- dplyr::filter(test_tx, fov == fov_use)
    segs_withCellType <- inner_join(test_segs, dplyr::filter(allCellIdents, sample == f), by = "barcode") %>%
      dplyr::filter(barcode %in% c(inter$t_cell, inter$o_cell))

    ggplot() +
      geom_path(data = test_segs, aes(x = x_global_px, y = y_global_px, group = paste(fov, cellID)),
                color = "white", linewidth = 0.5) +
      geom_path(data = segs_withCellType,
                aes(x = x_global_px, y = y_global_px, colour = cellType, group = paste(fov, cellID)),
                linewidth = 1.5) +
      geom_point(data = tx2, aes(x = x_global_px, y = y_global_px, fill = target), shape = 21, size = 4) +
      coord_fixed() +
      theme_dark() +
      theme(axis.text.x = element_text(angle = 90, vjust = 0.5, hjust = 1),
            panel.background = element_rect(fill = "black")) +
      big_text +
      paletteer::scale_color_paletteer_d("waRhol::skull_76_1") +
      paletteer::scale_fill_paletteer_d("wesanderson::Royal1") +
      ylim(ylim) + xlim(xlim) +
      labs(x = "X", y = "Y", colour = "Cell Type", fill = "Gene")
    ggsave(out_file, width = 7, height = 6)
  }

  examples <- tribble(
    ~panel,  ~sample,      ~fov, ~ligand,     ~t_gene, ~xlim,            ~ylim,
    "Fig4G", "Lung5_Rep1", 7,    "PDCD1LG2",  "CD8A",  c(13000, 13300),  c(159400, 159700),
    "Fig4F", NA,           NA,   "CD274",     "CD8A",  NULL,             NULL,
    "Fig3D", NA,           NA,   "PDCD1LG2",  "CD4",   NULL,             NULL,
    "Fig3E", NA,           NA,   "CD274",     "CD4",   NULL,             NULL)
  for (i in seq_len(nrow(examples))) {
    ex <- examples[i, ]
    if (is.na(ex$sample)) { message(ex$panel, ": example region not specified yet -- skipped"); next }
    make_example(ex$sample, ex$fov, ex$ligand, ex$t_gene, ex$xlim[[1]], ex$ylim[[1]],
                 fpath(paste0(ex$panel, "_cosmx_", ex$sample, ".jpg")))
  }
}

# =============================================================================
# CD8+ T cells -- Figure 4A-B (pseudotime), Figure 5B (TIGIT),
# Supplementary Figure 3G-I (naive / cytotoxic / exhaustion markers)
# Needs 03_t_cells/*
# =============================================================================
tcells <- function() {
  library(slingshot)
  library(scater)
  cd8_subset <- qs_read(dpath("cd8TCells.qs2"))
  sce_ss   <- qs_read(dpath("LungCohort", "allCD8_slingshotRes.qs2"))
  embedded <- qs_read(dpath("LungCohort", "allCD8_slingshotRes_umapEmbed.qs2"))

  traj_theme <- theme(axis.text = element_text(size = 16), axis.title = element_text(size = 20),
                      legend.text = element_text(size = 16), legend.title = element_text(size = 20),
                      title = element_text(size = 20))

  # 4A: lineage 1 pseudotime with its principal curve
  embedded_1 <- slingCurves(embedded)[[1]]
  embedded_1_df <- data.frame(embedded_1$s[embedded_1$ord, ])
  plotUMAP(sce_ss, colour_by = "slingPseudotime_1") +
    geom_path(data = dplyr::filter(embedded_1_df, umap_1 <= 4 | umap_2 >= 0),
              aes(x = umap_1, y = umap_2), linewidth = 1.2) +
    paletteer::scale_color_paletteer_c("grDevices::Inferno") +
    labs(colour = "Pseudotime\nLineage 1") +
    traj_theme
  ggsave(fpath("Fig4A_CD8_pseudotime_lineage1.jpg"), width = 6, height = 4)

  # 4B: lineage 2
  embedded_2 <- slingCurves(embedded)[[3]]
  embedded_2_df <- data.frame(embedded_2$s[embedded_2$ord, ])
  plotUMAP(sce_ss, colour_by = "slingPseudotime_3") +
    geom_path(data = embedded_2_df, aes(x = umap_1, y = umap_2), linewidth = 1.2) +
    paletteer::scale_color_paletteer_c("grDevices::Inferno") +
    labs(colour = "Pseudotime\nLineage 2") +
    traj_theme
  ggsave(fpath("Fig4B_CD8_pseudotime_lineage2.jpg"), width = 6, height = 4)

  # Supp 3G-I and 5B: mean expression of marker sets
  DefaultAssay(cd8_subset) <- "RNA"
  marker_umap <- function(genes, label, limits, file) {
    cd8_subset$score <- if (length(genes) > 1) colMeans(cd8_subset[["RNA"]]$data[genes, ]) else
      cd8_subset[["RNA"]]$data[genes, ]
    FeaturePlot(cd8_subset, reduction = "umap", features = "score") +
      ggtitle(NULL) +
      paletteer::scale_color_paletteer_c("grDevices::Sunset", limits = limits) +
      labs(colour = label, x = "UMAP 1", y = "UMAP 2") +
      traj_theme
    ggsave(fpath(file), width = 6, height = 4)
  }
  marker_umap(c("CCR7", "SELL", "LEF1"), "CCR7, SELL,\nLEF1 Average\nExpression", c(0, 3.5),
              "SuppFig3G_CD8_naive_markers.jpg")
  marker_umap(c("GZMB", "PRF1", "IFNG"), "GZMB, PRF1,\nIFNG Average\nExpression", c(0, 3.5),
              "SuppFig3H_CD8_cytotoxic_markers.jpg")
  marker_umap(c("PDCD1", "LAG3", "HAVCR2"), "PDCD1, LAG3,\nHAVCR2 Average \nExpression", c(0, 1.5),
              "SuppFig3I_CD8_exhaustion_markers.jpg")
  marker_umap("TIGIT", "TIGIT\nExpression", NULL, "Fig5B_CD8_TIGIT.jpg")
}

# =============================================================================
# Supplementary Figure 3A-F -- T-cell UMAPs
# Needs 03_t_cells/* 
# =============================================================================
# Flexible trailing-repeat stripper
# - Works with multiple separators (default: "_", ".", "-")
# - Vectorized over character vector x
# - Removes one trailing repeat of a prefix separated by one of the allowed separators
strip_trailing_repeat <- function(x, seps = c("_", ".", "-")) {
  stopifnot(is.character(x), length(seps) >= 1)
  vapply(x, function(s) {
    n <- nchar(s)
    if (n == 0L) return(s)

    # Build a regex class for separators, escapable (e.g., ".")
    sep_class <- paste0("[", paste0(gsub("([][\\^$.|?*+(){}\\\\-])", "\\\\\\1", seps), collapse = ""), "]")

    pos <- gregexpr(sep_class, s, perl = TRUE)[[1]]
    if (identical(pos, -1L)) return(s)

    for (i in rev(pos)) {
      # suffix = part after this separator
      suffix <- substr(s, i + 1L, n)
      if (nchar(suffix) == 0L) next
      # If the string STARTS with that suffix, it's a trailing repeat of the prefix
      if (startsWith(s, suffix)) {
        # Return the portion before this separator
        return(substr(s, 1L, i - 1L))
      }
    }
    s
  }, character(1))
}

supp3 <- function() {
  tCells <- readRDS(dpath("LungCohort", "allLung_NK-T_cells_publicData.RDS"))
  tCells <- RenameCells(tCells, new.names = sapply(colnames(tCells), strip_trailing_repeat))

  tCellIdents <- fread(dpath("LungCohort", "tCellIdentities.csv")) %>%
    mutate(broadType = case_when(grepl("CD8|Lin", identity) ~ "CD8+",
                                 grepl("CD4", identity) ~ "CD4+",
                                 .default = identity)) %>%
    column_to_rownames(var = "barcode")
  tCells <- AddMetaData(tCells, tCellIdents)
  tCells <- RunUMAP(tCells, dims = 1:15, reduction = "pca", return.model = TRUE)
  tFiltered <- qs_read(dpath("tFiltered_postCC_wAnnot.qs2"))

  umap_theme <- theme(axis.text = element_text(size = 16), axis.title = element_text(size = 20),
                      legend.text = element_text(size = 16), legend.title = element_text(size = 20),
                      title = element_text(size = 20))

  # project round-2 cells (not in the reference) onto a reference UMAP
  # anchor_reduction / map_reduction as used for each object in the original
  project_new <- function(reference, new_cells, anchor_reduction = "pca", map_reduction = "pca") {
    query <- subset(tFiltered, cells = new_cells) %>%
      NormalizeData() %>% FindVariableFeatures() %>% ScaleData() %>% RunPCA()
    anchors <- FindTransferAnchors(reference = reference, query = query, dims = 1:30,
                                   reference.reduction = anchor_reduction)
    query <- MapQuery(anchorset = anchors, reference = reference, query = query,
                      refdata = list(identity = "identity", broadType = "broadType"),
                      reference.reduction = map_reduction, reduction.model = "umap")
    as.data.frame(query[["ref.umap"]]@cell.embeddings) %>% `colnames<-`(c("umap_1", "umap_2")) %>%
      rbind(as.data.frame(reference[["umap"]]@cell.embeddings)) %>%
      slice_sample(prop = 1) %>%
      rownames_to_column(var = "barcode") %>%
      full_join(data.frame(barcode = colnames(tFiltered), cancerSubtype = tFiltered$cancerSubtype),
                by = "barcode") %>%
      full_join(rownames_to_column(tCellIdents, var = "barcode"), by = "barcode") %>%
      drop_na()
  }

  # S3A-B: all T cells by disease state and subtype
  umapCoords <- project_new(tCells, colnames(tFiltered)[!(colnames(tFiltered) %in% colnames(tCells))])
  ggplot(umapCoords, aes(x = umap_1, umap_2, colour = cancerSubtype)) +
    geom_point(size = 0.2, alpha = 0.8) + theme_minimal() + scale_colour_jama() +
    labs(colour = "Disease State", x = "UMAP 1", y = "UMAP 2") + umap_theme
  ggsave(fpath("SuppFig3A_Tcells_diseaseState.jpg"), width = 8, height = 4)
  ggplot(umapCoords, aes(x = umap_1, umap_2, colour = broadType)) +
    geom_point(size = 0.2, alpha = 0.8) + theme_minimal() +
    paletteer::scale_color_paletteer_d("ggthemes::colorblind") +
    labs(colour = "Cell Type", x = "UMAP 1", y = "UMAP 2") + umap_theme
  ggsave(fpath("SuppFig3B_Tcells_subtype.jpg"), width = 8, height = 4)
  write_csv(umapCoords, dpath("allTCells_umapCoords_wMeta.csv"))

  # S3C-E: CD4+ T cells
  tCell_list <- qs_read(dpath("tCellSubtyping_inProgress.qs2"))
  cd4 <- AddMetaData(tCell_list[[3]], tCellIdents)
  cd4 <- RunUMAP(cd4, dims = 1:15, reduction = "harmony", return.model = TRUE)

  genes <- c("IFNG", "GZMB", "SELL", "CCR7", "CXCR6", "CXCL13", "FOXP3", "IL2RA", "MKI67")
  FeaturePlot(cd4, reduction = "umap", features = genes, raster = FALSE) &
    paletteer::scale_color_paletteer_c("viridis::magma", trans = "log1p")
  ggsave(fpath("SuppFig3C_CD4_markers.jpg"), width = 8, height = 8)

  cd4_new <- colnames(tFiltered)[which(!(colnames(tFiltered) %in% colnames(cd4)) &
                                         grepl("^Treg|CD4", tFiltered$predicted.id))]
  cd4_umapCoords <- project_new(cd4, cd4_new) %>%
    dplyr::filter(grepl("CD4|Treg", identity))
  ggplot(cd4_umapCoords, aes(x = umap_1, umap_2, colour = cancerSubtype)) +
    geom_point(size = 0.2, alpha = 0.8) + theme_minimal() + scale_colour_jama() +
    labs(colour = "Disease State", x = "UMAP 1", y = "UMAP 2") + umap_theme +
    theme(legend.position = "bottom") + guides(color = guide_legend(nrow = 2))
  ggsave(fpath("SuppFig3D_CD4_diseaseState.jpg"), width = 6, height = 7)

  DimPlot(cd4, reduction = "umap", group.by = "identity") +
    ggtitle(NULL) +
    theme(axis.text = element_text(size = 16), axis.title = element_text(size = 20),
          legend.text = element_text(size = 16), legend.title = element_text(size = 20)) +
    paletteer::scale_color_paletteer_d("NatParksPalettes::GrandCanyon")
  ggsave(fpath("SuppFig3E_CD4_subtype.jpg"), width = 5, height = 4)

  # S3F: CD8+ T cells by disease state
  cd8_subset <- AddMetaData(qs_read(dpath("cd8TCells.qs2")), tCellIdents)
  cd8_subset <- RunUMAP(cd8_subset, dims = 1:15, reduction = "harmony", return.model = TRUE)
  cd8_new <- colnames(tFiltered)[which(!(colnames(tFiltered) %in% colnames(cd8_subset)) &
                                         grepl("^Lin", tFiltered$predicted.id))]
  cd8_umapCoords <- project_new(cd8_subset, cd8_new, map_reduction = "harmony")
  ggplot(cd8_umapCoords, aes(x = umap_1, umap_2, colour = cancerSubtype)) +
    geom_point(size = 0.2, alpha = 0.8) + theme_minimal() + scale_colour_jama() +
    labs(colour = "Disease State", x = "UMAP 1", y = "UMAP 2") + umap_theme
  ggsave(fpath("SuppFig3F_CD8_diseaseState.jpg"), width = 6, height = 4)
}
